INSERT INTO filme (id, titulo, descricao, diretor, imagem_url, categoria_id) VALUES (9, 'The Godfather', 'O Poderoso Chefão acompanha a poderosa família mafiosa Corleone na Nova York do pós-guerra, revelando alianças, rivalidades e a transição de poder do patriarca Vito para o filho Michael', 'Coppola', 'https://th.bing.com/th/id/OIP.cxa0kYJ_qucjCQNBb0lKigHaLH?w=208&h=305&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3', 1);
INSERT INTO filme (id, titulo, descricao, diretor, imagem_url, categoria_id) VALUES (11, 'The Godfather Part II', 'O Poderoso Chefão: Parte II alterna entre a juventude de Vito Corleone e a consolidação de poder de Michael, agora líder da família nos anos 1950, explorando temas de ambição, lealdade e traição.', 'Coppola', 'https://th.bing.com/th/id/OIP.ux3uXgsliJokECEcHVAQrgHaKj?w=208&h=297&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3', 1);
INSERT INTO filme (id, titulo, descricao, diretor, imagem_url, categoria_id) VALUES (12, 'The Godfather Part III', 'O Poderoso Chefão: Parte III acompanha Michael Corleone, agora envelhecido, tentando legitimar os negócios da família e buscar redenção, enquanto lida com intrigas envolvendo o Vaticano, disputas de poder e um romance proibido que ameaça sua filha', 'Coppola', 'https://media.themoviedb.org/t/p/w600_and_h900_face/y8GROCjgD8amoFufSx2USKrOy7d.jpg', 1);
INSERT INTO filme (id, titulo, descricao, diretor, imagem_url, categoria_id) VALUES (13, 'Shawshank Redemption', 'Um Sonho de Liberdade é um aclamado filme de drama de 1994 que narra a história de esperança, amizade e resiliência dentro de uma prisão', 'Frank Darabont', 'https://media.themoviedb.org/t/p/w600_and_h900_face/umX3lBhHoTV7Lsci140Yr8VpXyN.jpg', 3);
INSERT INTO filme (id, titulo, descricao, diretor, imagem_url, categoria_id) VALUES (14, 'Taxi Driver', 'Taxi Driver acompanha Travis Bickle, um veterano solitário da Guerra do Vietnã que trabalha como taxista nas madrugadas de Nova York, imerso em um ambiente de decadência moral e criminalidade.', 'Scorsese', 'https://th.bing.com/th/id/OIP.4N9EMatlwSAvZUcwnVDrQwHaLH?w=208&h=305&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3', 3);